/* The bench screens' big digits (scr_font.c, generated by tools/make_scr_font.py): 0-9 . - C and ^, the
 * degree sign, 16 pixels tall, each its own width. App/scr_view.c draws them (scr_big_text). Pure C. */
#ifndef SCR_FONT_H
#define SCR_FONT_H

#include <stdint.h>

#define SCR_BIG_H 16
#define SCR_BIG_GAP 2                               /* pixels between two glyphs */

extern const char scr_big_chars[];                  /* the characters drawn, sorted */
extern const uint8_t scr_big_w[];                   /* their widths */
extern const uint16_t scr_big_rows[][SCR_BIG_H];    /* their rows, in the same order */

#endif
